<?php
declare(strict_types=1); namespace App\Entity; use App\Repository\ApplicationRepository; use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity(repositoryClass:ApplicationRepository::class),ORM\UniqueConstraint(name:'candidate_job_unique',columns:['candidate_id','job_id'])] class Application {
 public const STATUSES=['SUBMITTED','UNDER_REVIEW','INTERVIEW','ACCEPTED','REJECTED','WITHDRAWN']; #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne(inversedBy:'applications'),ORM\JoinColumn(nullable:false,onDelete:'CASCADE')] private ?Candidate $candidate=null; #[ORM\ManyToOne(inversedBy:'applications'),ORM\JoinColumn(nullable:false,onDelete:'CASCADE')] private ?Job $job=null; #[ORM\Column(type:'text',nullable:true)] private ?string $coverLetter=null; #[ORM\Column(length:30)] private string $status='SUBMITTED'; #[ORM\Column] private \DateTimeImmutable $submittedAt;
 public function __construct(){ $this->submittedAt=new \DateTimeImmutable(); } public function getId():?int{return $this->id;} public function getCandidate():?Candidate{return $this->candidate;} public function setCandidate(Candidate $v):self{$this->candidate=$v;return $this;} public function getJob():?Job{return $this->job;} public function setJob(Job $v):self{$this->job=$v;return $this;} public function getCoverLetter():?string{return $this->coverLetter;} public function setCoverLetter(?string $v):self{$this->coverLetter=$v;return $this;} public function getStatus():string{return $this->status;} public function setStatus(string $v):self{$this->status=$v;return $this;} public function getSubmittedAt():\DateTimeImmutable{return $this->submittedAt;} }
